import torch
import torch.nn as nn
import torch.nn.functional as F
from torch.utils.cpp_extension import load_inline

frobenius_norm_source = r'''
#include <torch/extension.h>
#include <cuda_runtime.h>
#include <cmath>

// Kernel for summing squares
__global__ void reduce_square_sum_kernel(const float* __restrict__ x, float* __restrict__ out, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        atomicAdd(out, x[idx] * x[idx]);
    }
}

// Kernel for elementwise division
__global__ void elementwise_divide_kernel(const float* __restrict__ x, float* __restrict__ out, float norm, int size) {
    int idx = blockIdx.x * blockDim.x + threadIdx.x;
    if (idx < size) {
        out[idx] = x[idx] / norm;
    }
}

torch::Tensor frobenius_norm_cuda(torch::Tensor x) {
    // Create accumulator for sum of squares
    auto out_sum = torch::zeros({1}, x.options());
    int size = x.numel();

    // Launch reduce square sum kernel
    const int blockSize = 256;
    const int gridSize = (size + blockSize - 1) / blockSize;
    reduce_square_sum_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        out_sum.data_ptr<float>(),
        size
    );
    cudaDeviceSynchronize();

    // Copy sum of squares to CPU and compute sqrt
    float total = out_sum[0].item<float>();
    float norm_val = std::sqrt(total);

    // Allocate output
    auto out_tensor = torch::empty_like(x);

    // Launch elementwise division kernel
    elementwise_divide_kernel<<<gridSize, blockSize>>>(
        x.data_ptr<float>(),
        out_tensor.data_ptr<float>(),
        norm_val,
        size
    );
    return out_tensor;
}
'''

frobenius_norm_cpp_source = "torch::Tensor frobenius_norm_cuda(torch::Tensor x);"

frobenius_norm = load_inline(
    name="frobenius_norm",
    cpp_sources=frobenius_norm_cpp_source,
    cuda_sources=frobenius_norm_source,
    functions=["frobenius_norm_cuda"],
    verbose=True,
    extra_cflags=[""],
    extra_ldflags=[""],
)


class ModelNew(nn.Module):
    """
    Optimized model using a custom CUDA operator for Frobenius norm normalization.
    """
    def __init__(self):
        super(ModelNew, self).__init__()
        self.frobenius_norm = frobenius_norm

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        return self.frobenius_norm.frobenius_norm_cuda(x)
